import{_ as s,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"LoadData（BitMode卷积数据搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_3D_BitMode"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_3D_BitMode.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_3D_BitMode.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),l={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_3D_BitMode.md"};function c(i,a,e,d,o,r){return n(),p("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>LoadData（BitMode卷积数据搬运）<a id="ZH-CN_TOPIC_0000002517284408"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>LoadData（BitMode卷积数据搬运）用于完成image to column操作，将多维feature map转为二维矩阵。支持的数据通路为：L1 Buffer-&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer。</p><p>本接口与LoadData（卷积数据搬运）接口的差异在于参数的传入方式不同，本接口传入的是一个联合体结构Load3DBitModeParam。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="n">TPosition</span><span class="w"> </span><span class="n">Dst</span><span class="p">,</span><span class="w"> </span><span class="n">TPosition</span><span class="w"> </span><span class="n">Src</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadData</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Load3DBitModeParam</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明<span id="table07381635103112"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。</td></tr><tr><td>Src</td><td>源操作数存储的逻辑位置（TPosition），仅本接口使用。</td></tr><tr><td>Dst</td><td>目的操作数存储的逻辑位置（TPosition），仅本接口使用。</td></tr></tbody></table><p><strong>表2</strong> 通用参数说明<span id="table18368155193919"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下：<br>  • A2：ZZ格式/NZ格式；<br>  • B2：ZN格式；<br>  • A1/B1：无格式要求，一般情况下为NZ格式。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor。<br>数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为：<br>  • Load3DBitModeParam，具体参考<a href="#table106611666584">表3</a>。<br>上述结构体参数定义请参考<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表3</strong> Load3DBitModeParam类参数说明<span id="table106611666584"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与Load3DBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>Load3DBitModeConfig0位域（bit-field）结构体类型，参数参考<a href="#table184321224173">表4</a>，与config0组成联合体（union）。</td></tr><tr><td>config1</td><td>uint64_t类型，与Load3DBitModeConfig1位域（bit-field）结构体类型参数config1BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig1()函数获取其值。</td></tr><tr><td>config1BitMode</td><td>Load3DBitModeConfig1位域（bit-field）结构体类型，参数参考<a href="#table87491086815">表5</a>，与config1组成联合体（union）。</td></tr></tbody></table><p>Load3DBitModeParam类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>Load3DBitModeParam类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数。</p><p>与使用LoadData3DParamsV2结构体的LoadData（卷积数据搬运）接口相比，减少了scalar计算，实现性能提升。</p><p>Load3DBitModeParam类可以直接使用LoadData3DParamsV2结构体类型对象初始化：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">Load3DBitModeParam</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LoadData3DParamsV2</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">loadData3DParams_</span><span class="p">);</span>
</code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对config0和config1直接进行逐bit位修改来修改参数。</p><p><strong>表4</strong> Load3DBitModeConfig0结构体参数说明<span id="table184321224173"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>kStep</td><td>该指令在目的操作数width维度的传输长度，如果不覆盖最右侧的分形，对于half类型，应为16的倍数，对于int8_t/uint8_t应为32的倍数；覆盖的情况则无倍数要求。取值范围：kStep∈[1, 65535]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的kExtension含义相同）。<br>该参数是位域结构体的最低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetKExtension()函数设置其值，使用GetKExtension()函数获取其值。</td></tr><tr><td>mStep</td><td>该指令在目的操作数height维度的传输长度，如果不覆盖最下侧的分形，对于half/int8_t/uint8_t，应为16的倍数；覆盖的情况则无倍数要求。取值范围：mStep∈[1, 65535]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的mExtension含义相同）。<br>该参数是位域结构体的第二低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetMExtension()函数设置其值，使用GetMExtension()函数获取其值。</td></tr><tr><td>kPos</td><td>该指令在目的操作数width维度的起点，对于half类型，应为16的倍数，对于int8_t/uint8_t应为32的倍数。取值范围[0, 65535]。默认为0。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的kStartPt含义相同）。<br>该参数是位域结构体的第三低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetKStartPt()函数设置其值，使用GetKStartPt()函数获取其值。</td></tr><tr><td>mPos</td><td>该指令在目的操作数height维度的起点，取值范围[0, 32767]。默认为0。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的mStartPt含义相同）。<br>该参数是位域结构体的最高位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetMStartPt()函数设置其值，使用GetMStartPt()函数获取其值。</td></tr></tbody></table><p><strong>表5</strong> Load3DBitModeConfig1结构体参数说明<span id="table87491086815"></span></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>strideW</td><td>卷积核在源操作数width维度滑动的步长，取值范围：strideW∈[1, 63]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的strideW含义相同）。<br>该参数是位域结构体的最低位参数，占用6bit，可以使用Load3DBitModeParam类对象的SetStrideW()函数设置其值，使用GetStrideW()函数获取其值。</td></tr><tr><td>strideH</td><td>卷积核在源操作数height维度滑动的步长，取值范围：strideH∈[1, 63]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的strideH含义相同）<br>该参数是位域结构体的第二低位参数，占用6bit，可以使用Load3DBitModeParam类对象的SetStrideH()函数设置其值，使用GetStrideH()函数获取其值。</td></tr><tr><td>Wk</td><td>卷积核width，取值范围：Wk∈[1, 255]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的filterW含义相同）。<br>该参数是位域结构体的第三低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetFilterW()函数设置其值，使用GetFilterW()函数获取其值。</td></tr><tr><td>Hk</td><td>卷积核height，取值范围：Hk∈[1, 255]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的filterH含义相同）。<br>该参数是位域结构体的第四低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetFilterH()函数设置其值，使用GetFilterH()函数获取其值。</td></tr><tr><td>dilationW</td><td>卷积核width膨胀系数，取值范围：dilationW∈[1, 255]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的dilationFilterW含义相同）<br>该参数是位域结构体的第五低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetDilationFilterW()函数设置其值，使用GetDilationFilterW()函数获取其值。</td></tr><tr><td>dilationH</td><td>卷积核height膨胀系数，取值范围：dilationH∈[1, 255]。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的dilationFilterH含义相同）。<br>该参数是位域结构体的第六低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetDilationFilterH()函数设置其值，使用GetDilationFilterH()函数获取其值。</td></tr><tr><td>filterW</td><td>是否在filterW的基础上将卷积核width增加256个元素。true，增加；false，不增加。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的filterSizeW含义相同）。<br>该参数是位域结构体的第七低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFilterSizeW()函数设置其值，使用GetFilterSizeW()函数获取其值。</td></tr><tr><td>filterH</td><td>是否在filterH的基础上将卷积核height增加256个元素。true，增加；false，不增加。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的filterSizeH含义相同）。<br>该参数是位域结构体的第八低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFilterSizeH()函数设置其值，使用GetFilterSizeH()函数获取其值。</td></tr><tr><td>transpose</td><td>是否启用转置功能，对整个目标矩阵进行转置，支持数据类型为bool，仅在目的TPosition为A2，且源操作数为half类型时有效。默认为false。<br>  • true：启用<br>  • false：不启用<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的enTranspose含义相同）。<br>该参数是位域结构体的第九低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetTranspose()函数设置其值，使用GetTranspose()函数获取其值。</td></tr><tr><td>fmatrixCtrl</td><td>表示LoadData3DV2指令从左矩阵还是右矩阵获取FeatureMap的属性描述，与SetFmatrix配合使用，当前只支持设置为false，默认值为false。<br>  • true：从右矩阵中获取FeatureMap的属性描述；<br>  • false：从左矩阵中获取FeatureMap的属性描述。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的fMatrixCtrl含义相同）。<br>该参数是位域结构体的第十低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFmatrixCtrl()函数设置其值，使用GetFmatrixCtrl()函数获取其值。</td></tr><tr><td>sizeChannel</td><td>源操作数的通道数，取值范围：sizeChannel∈[1, 63]。<br>sizeChannel的取值要求为：对于uint32_t/int32_t/float，sizeChannel可取值为4，N*8，N*8+4；对于half/bfloat16，sizeChannel可取值为4，8，N*16，N*16+4，N*16+8；对于int8_t/uint8_t，sizeChannel可取值为4，8，16，32*N，N*32+4，N*32+8，N*32+16；对于int4b_t，sizeChannel可取值为8，16，32，N * 64，N*64+8，N*64+16，N*64+32。N为正整数。<br>（与<a href="LoadData_3D.html">LoadData（卷积数据搬运）</a>中的channelSize含义相同）。<br>该参数是位域结构体的最高位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetChannelSize()函数设置其值，使用GetChannelSize()函数获取其值。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持数据类型为：int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t、int32_t、uint32_t、float。</p><h2 id="返回值说明">返回值说明<a id="section640mcpsimp"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<a id="section6461234123118"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>示例代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// featureMapA1为half类型、位于L1 Buffer，featureMapA2为half类型、位于L0A Buffer</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">H</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="n">W</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">Kh</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">Kw</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">C0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">dilationH</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">dilationW</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">padTop</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">padBottom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">padLeft</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">padRight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">strideH</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">strideW</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">padList</span><span class="p">[</span><span class="mi">4</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="n">padLeft</span><span class="p">,</span><span class="w"> </span><span class="n">padRight</span><span class="p">,</span><span class="w"> </span><span class="n">padTop</span><span class="p">,</span><span class="w"> </span><span class="n">padBottom</span><span class="p">};</span>

<span class="c1">// 使用LoadData3DParamsV2结构体对象初始化Load3DBitModeParam</span>
<span class="c1">// 构造参数顺序：padList, l1H, l1W, sizeChannel, kExtension, mExtension, kStartPt, mStartPt,</span>
<span class="c1">//             strideW, strideH, filterW, filterH, dilationFilterW, dilationFilterH,</span>
<span class="c1">//             enTranspose, enSmallK, padValue, filterSizeW, filterSizeH, fMatrixCtrl</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData3DParamsV2</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">param</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">padList</span><span class="p">,</span><span class="w"> </span><span class="n">H</span><span class="p">,</span><span class="w"> </span><span class="n">W</span><span class="p">,</span><span class="w"> </span><span class="n">C0</span><span class="p">,</span><span class="w"> </span><span class="n">C0</span><span class="p">,</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint16_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">H</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">W</span><span class="p">),</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span>
<span class="w">    </span><span class="n">strideW</span><span class="p">,</span><span class="w"> </span><span class="n">strideH</span><span class="p">,</span><span class="w"> </span><span class="n">Kw</span><span class="p">,</span><span class="w"> </span><span class="n">Kh</span><span class="p">,</span><span class="w"> </span><span class="n">dilationW</span><span class="p">,</span><span class="w"> </span><span class="n">dilationH</span><span class="p">,</span>
<span class="w">    </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="p">(</span><span class="n">half</span><span class="p">)</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">};</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Load3DBitModeParam</span><span class="w"> </span><span class="nf">paramBitMode</span><span class="p">(</span><span class="n">param</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A2</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">featureMapA2</span><span class="p">,</span><span class="w"> </span><span class="n">featureMapA1</span><span class="p">,</span><span class="w"> </span><span class="n">paramBitMode</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const m=s(l,[["render",c]]);export{b as __pageData,m as default};
